        "testata": "South China Morning Post",
        "lingua_originale": "en",
        "titolo_orig": "AI agents face trust issues in ‘high-risk’ industrial sectors: experts",
        "testo_it": "Esperti avvertono sui rischi di affidabilità degli agenti IA nei settori industriali critici.",
        "priorita": "Bassa",
        "id_gruppo": 14,
